CREATE TABLE sidebar_apps (id BIGSERIAL PRIMARY KEY, uuid UUID NOT NULL DEFAULT gen_random_uuid() UNIQUE, organization_id BIGINT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,name TEXT NOT NULL CHECK(length(name) BETWEEN 1 AND 120),url TEXT NOT NULL,icon TEXT NOT NULL DEFAULT '',placement TEXT NOT NULL CHECK(placement IN ('conversation_sidebar','contact_panel','nav')),scopes TEXT[] NOT NULL DEFAULT '{}',enabled BOOLEAN NOT NULL DEFAULT false,revision INTEGER NOT NULL DEFAULT 1,created_by BIGINT NOT NULL REFERENCES users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX idx_sidebar_apps_org ON sidebar_apps(organization_id);
CREATE TRIGGER trg_sidebar_apps_updated BEFORE UPDATE ON sidebar_apps FOR EACH ROW EXECUTE FUNCTION set_updated_at();
